import { SheetBody } from '../../slots/defs/sheetBody';
import { useClaims } from '../claims/useClaims';
import { GRADES, usePeople } from '../people/usePeople';
import { usePeriodDueTotals } from '../periods/usePeriodDueTotals';
import { usePeriods } from '../periods/usePeriods';
import { useDueTotals } from '../rates/useDueTotals';
import { sumDues } from '../rates/useRates';

/** The statuses the summary counts; no claim is PENDING today, so its count stays 0. */
const STATUSES: string[] = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'];

/** The sheet's summary, worked out from the same figures the lists show: per grade, how many people
 *  have it on the sheet's today (retired people left out) and their due-totals added up (skipping
 *  'n/a'); per period, its due-total; per status, how many claims have it. */
function Summary({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const periods = usePeriods(sheetId);
  const dueTotals = useDueTotals(sheetId);
  const periodTotals = usePeriodDueTotals(sheetId);
  const active = (people.data ?? []).filter((p) => !p.retiredFrom);
  return (
    <section data-testid="summary">
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due total</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const onGrade = active.filter((p) => p.grade === g);
            return (
              <tr key={g}>
                <td>{g}</td>
                <td data-testid={`summary-grade-${g}-count`}>{onGrade.length}</td>
                <td data-testid={`summary-grade-${g}-due-total`}>
                  {sumDues(onGrade.map((p) => dueTotals.get(p.id) ?? 'n/a'))}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Period</th>
            <th>Due total</th>
          </tr>
        </thead>
        <tbody>
          {(periods.data ?? []).map((p) => (
            <tr key={p.id}>
              <td>{p.name}</td>
              <td data-testid={`summary-period-${p.name}-due-total`}>{periodTotals.get(p.name) ?? ''}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Status</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {STATUSES.map((s) => (
            <tr key={s}>
              <td>{s}</td>
              <td data-testid={`summary-status-${s}-count`}>
                {(claims.data ?? []).filter((c) => c.status === s).length}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 40, Component: ({ sheetId }) => <Summary sheetId={sheetId} /> });
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSingleFlight } from '../../query/useSingleFlight';
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { SheetBody } from '../../slots/defs/sheetBody';
import { GRADES } from '../people/usePeople';
import { useSheetToday } from '../today/useSheetToday';
import { useDueTotals } from './useDueTotals';
import { rateFor, ratesKey, sumDues, useRates, type Rate } from './useRates';

/** The sheet's rates for each grade: a form that sets one from an optional from-date (replacing the
 *  grade's rate from that date; blank is from the beginning of time), the rates set, and the rate in
 *  force on the sheet's today for every grade ('n/a' when none is). */
function Rates({ sheetId }: { sheetId: string }) {
  const rates = useRates(sheetId);
  const today = useSheetToday(sheetId);
  const queryClient = useQueryClient();
  const [grade, setGrade] = useState<string>('A');
  const [pct, setPct] = useState('');
  const [from, setFrom] = useState('');

  const submitOnce = useSingleFlight();
  const save = useMutation({
    mutationFn: (f: { grade: string; pct: string; from: string }) =>
      postJson<Rate>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`, f),
    onSuccess: async () => {
      setPct('');
      setFrom('');
      await queryClient.invalidateQueries({ queryKey: ratesKey(sheetId) });
    },
  });

  return (
    <section data-testid="rates">
      <form
        data-testid="rate-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            save.reset();
            return save.mutateAsync({ grade, pct, from });
          });
        }}
      >
        <label>
          Grade{' '}
          <select
            data-testid="rate-form-grade"
            value={grade}
            onChange={(e) => {
              setGrade(e.target.value);
              save.reset();
            }}
          >
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          Rate %{' '}
          <input
            data-testid="rate-form-pct"
            inputMode="decimal"
            value={pct}
            onChange={(e) => {
              setPct(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <label>
          From{' '}
          <input
            type="text"
            placeholder="yyyy-mm-dd"
            data-testid="rate-form-from"
            value={from}
            onChange={(e) => {
              setFrom(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="rate-form-submit" disabled={save.isPending}>
          Set rate
        </button>
        {save.isError && <p data-testid="rate-form-error">{save.error.message}</p>}
      </form>
      <table data-testid="rates-list">
        <thead>
          <tr>
            <th>Grade</th>
            <th>Rate %</th>
            <th>From</th>
          </tr>
        </thead>
        <tbody>
          {(rates.data ?? []).map((r) => (
            <tr key={`${r.grade}-${r.from ?? 'start'}`} data-testid={`rate-row-${r.grade}-${r.from ?? 'start'}`}>
              <td data-testid="rate-grade">{r.grade}</td>
              <td data-testid="rate-pct">{r.pct}</td>
              <td data-testid="rate-from">{r.from ?? ''}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <p>
        Current rates:{' '}
        {GRADES.map((g) => (
          <span key={g}>
            {g} <strong data-testid={`rate-current-${g}`}>{rateFor(rates.data, g, today.data?.today) ?? 'n/a'}</strong>{' '}
          </span>
        ))}
      </p>
      {rates.isError && <p data-testid="rates-error">{rates.error.message}</p>}
    </section>
  );
}

function PersonDueTotal({ sheetId, personId }: { sheetId: string; personId: number }) {
  const totals = useDueTotals(sheetId);
  return <td data-testid="person-due-total">{totals.get(personId) ?? ''}</td>;
}

/** The sheet's due-total: everyone's due-total added up, skipping 'n/a'. */
function DueTotal({ sheetId }: { sheetId: string }) {
  const totals = useDueTotals(sheetId);
  return (
    <p>
      Due total: <strong data-testid="rollup-due-total">{sumDues([...totals.values()])}</strong>
    </p>
  );
}

export const contributions = [
  SheetBody.fill({ order: 5, Component: ({ sheetId }) => <Rates sheetId={sheetId} /> }),
  PersonColumnHead.fill({ order: 20, Component: () => <th>Due</th> }),
  PersonCells.fill({ order: 20, Component: PersonDueTotal }),
  SheetBody.fill({ order: 30, Component: ({ sheetId }) => <DueTotal sheetId={sheetId} /> }),
];
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { SheetBody } from '../../slots/defs/sheetBody';
import { sumDues } from '../rates/useRates';
import { useOverdue } from './useOverdue';

/** A person's overdue count and overdue-total: their claims that count and are overdue, and the sum
 *  of those claims' figures. */
function PersonOverdue({ sheetId, personId }: { sheetId: string; personId: number }) {
  const figures = useOverdue(sheetId).get(personId);
  return (
    <>
      <td data-testid="person-overdue-count">{figures?.count ?? ''}</td>
      <td data-testid="person-overdue-total">{figures?.total ?? ''}</td>
    </>
  );
}

/** The sheet's overdue count and overdue-total: everyone's added up. */
function SheetOverdue({ sheetId }: { sheetId: string }) {
  const figures = [...useOverdue(sheetId).values()];
  return (
    <p>
      Overdue: <strong data-testid="rollup-overdue-count">{figures.reduce((n, f) => n + f.count, 0)}</strong>,
      total <strong data-testid="rollup-overdue-total">{sumDues(figures.map((f) => f.total))}</strong>
    </p>
  );
}

export const contributions = [
  PersonColumnHead.fill({ order: 25, Component: () => (
    <>
      <th>Overdue</th>
      <th>Overdue total</th>
    </>
  ) }),
  PersonCells.fill({ order: 25, Component: PersonOverdue }),
  SheetBody.fill({ order: 35, Component: ({ sheetId }) => <SheetOverdue sheetId={sheetId} /> }),
];
